import { fireEvent, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../types";
import { ToolExecutedEventInfo } from "./ToolExecutedEventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({
    title,
    onClose,
    children,
  }: {
    title: string;
    onClose: () => void;
    children: React.ReactNode;
  }) => (
    <div>
      <h1>{title}</h1>
      <button data-testid="event-details-close" onClick={onClose}>
        Close
      </button>
      {children}
    </div>
  ),
}));

const baseEvent: ConversationEvent = {
  __typename: "ConversationEvent",
  id: "1",
  conversationEventType: ConversationEventType.ToolExecuted,
  name: "event_name",
  actionText: "",
  flowId: "",
  slotValue: null,
  stepId: "",
  timestamp: new Date().toISOString(),
  originalTimestamp: 0,
  metadata: {
    tool_name: "my_tool",
    tool_arguments: { query: "hello" },
    tool_result: "some result",
    tool_is_error: false,
    tool_source: "local",
    parseData: {},
  },
};

describe("ToolExecutedEventInfo", () => {
  it("renders the Mantle title", () => {
    renderWithProviders(<ToolExecutedEventInfo event={baseEvent} onClose={vi.fn()} />);

    expect(screen.getByText("Tool executed")).toBeInTheDocument();
    expect(screen.queryByText("MCP tool executed")).not.toBeInTheDocument();
  });

  it("calls onClose when close button is clicked", () => {
    const onClose = vi.fn();
    renderWithProviders(<ToolExecutedEventInfo event={baseEvent} onClose={onClose} />);

    fireEvent.click(screen.getByTestId("event-details-close"));
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  describe("source and server", () => {
    it("always shows Source for a local tool", () => {
      renderWithProviders(<ToolExecutedEventInfo event={baseEvent} onClose={vi.fn()} />);

      expect(screen.getByText("Source")).toBeInTheDocument();
      expect(screen.getByText("local")).toBeInTheDocument();
      expect(screen.queryByText("Server")).not.toBeInTheDocument();
    });

    it("shows MCP source and server when set", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: {
          ...baseEvent.metadata,
          tool_source: "mcp",
          tool_mcp_server: "payments",
        },
      };

      renderWithProviders(<ToolExecutedEventInfo event={event} onClose={vi.fn()} />);

      expect(screen.getByText("Tool executed")).toBeInTheDocument();
      expect(screen.getByText("mcp")).toBeInTheDocument();
      expect(screen.getByText("payments")).toBeInTheDocument();
    });

    it("shows Source as an em dash when source is missing", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: {
          tool_name: "my_tool",
          parseData: {},
        },
      };

      renderWithProviders(<ToolExecutedEventInfo event={event} onClose={vi.fn()} />);

      expect(screen.getByText("Source")).toBeInTheDocument();
      expect(screen.getByTestId("event-tool-source")).toHaveTextContent("—");
      expect(screen.queryByText("mcp")).not.toBeInTheDocument();
    });
  });
});
